input.command:
mkdir -p /private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/cb29592c-9e41-4f66-8a89-43c35d7e49df/scratchpad
gh api graphql -f query='
query($owner:String!, $repo:String!, $pr:Int!, $cursor:String) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      reviewThreads(first:100, after:$cursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          isResolved
          isOutdated
          path
          line
          comments(first:20) {
            nodes {
              author { login }
              body
              createdAt
              url
            }
          }
        }
      }
    }
  }
}' -f owner=ZimmermannAU -f repo=zimmermann-pwa -F pr=71 > /private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/cb29592c-9e41-4f66-8a89-43c35d7e49df/scratchpad/pr71_threads.json 2>&1
echo "exit: $?"
wc -l /private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/cb29592c-9e41-4f66-8a89-43c35d7e49df/scratchpad/pr71_threads.json

SCRATCH=/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/cb29592c-9e41-4f66-8a89-43c35d7e49df/scratchpad
echo "--- comment counts per unresolved thread ---"
jq -r '
.data.repository.pullRequest.reviewThreads.nodes[]
| select(.isResolved==false)
| select([.comments.nodes[].author.login] | index("coderabbitai"))
| "\(.path):\(.line) -> \(.comments.nodes | length) comment(s), authors: \([.comments.nodes[].author.login] | join(", "))"
' "$SCRATCH/pr71_threads.json"

echo ""
echo "--- resolved threads (to sanity check count) ---"
jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==true)] | length' "$SCRATCH/pr71_threads.json"

echo ""
echo "--- all CodeRabbit reviews on this PR (author/state/submittedAt) ---"
gh api graphql -f query='
query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      reviews(first:50) {
        nodes { author { login } state submittedAt body }
      }
    }
  }
}' -f owner=ZimmermannAU -f repo=zimmermann-pwa -F pr=71 | jq -r '.data.repository.pullRequest.reviews.nodes[] | "\(.submittedAt) | \(.author.login) | \(.state) | " + (.body | split("\n")[0])'
